class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        java.util.Map<Integer, Integer> row = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> col = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> diag = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> anti = new java.util.HashMap<>();
        java.util.Set<Long> lampSet = new java.util.HashSet<>();
        for (int[] l : lamps) {
            long key = (long) l[0] * n + l[1];
            if (lampSet.add(key)) {
                row.merge(l[0], 1, Integer::sum);
                col.merge(l[1], 1, Integer::sum);
                diag.merge(l[0] - l[1], 1, Integer::sum);
                anti.merge(l[0] + l[1], 1, Integer::sum);
            }
        }
        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int r = queries[q][0], c = queries[q][1];
            if (row.getOrDefault(r, 0) > 0 || col.getOrDefault(c, 0) > 0 ||
                diag.getOrDefault(r - c, 0) > 0 || anti.getOrDefault(r + c, 0) > 0)
                ans[q] = 1;
            for (int dr = -1; dr <= 1; dr++)
                for (int dc = -1; dc <= 1; dc++) {
                    int nr = r + dr, nc = c + dc;
                    long key = (long) nr * n + nc;
                    if (lampSet.remove(key)) {
                        row.merge(nr, -1, Integer::sum);
                        col.merge(nc, -1, Integer::sum);
                        diag.merge(nr - nc, -1, Integer::sum);
                        anti.merge(nr + nc, -1, Integer::sum);
                    }
                }
        }
        return ans;
    }
}

